INSERT INTO services (service_id,name,sub_category,gov_level,description,eligibility,benefits,application_mode,processing_time,fees,validity,official_portal,official_apply_link,helpline_number,email,office_locator,languages_available,keywords,ai_summary,ai_explanation,ai_common_questions,ai_common_mistakes,ai_followup_questions,ai_search_keywords,source_url,source_type,last_updated,version,content_hash) VALUES ('CEN-TRN-DL-009','Driving Licence (Sarathi / Parivahan)','Licensing','central','Application for learner''s licence, driving licence, and renewals through the Parivahan Sarathi portal.','Minimum age 16 (gearless <50cc) / 18 (LMV); pass driving test.','Legal authorisation to drive; valid identity/address proof.','both','Learner''s licence same day (online test); DL after driving test, ~7-30 days.','Learner''s ~Rs.150; DL ~Rs.200+ (varies by state RTO).','20 years or until age 40 (whichever earlier), then renewable.','https://parivahan.gov.in','https://sarathi.parivahan.gov.in','0120-2459169','helpdesk-sarathi@gov.in','Regional Transport Office (RTO) locator on Parivahan.','{"en","hi","regional"}','{"driving licence","sarathi","parivahan","rto","learner licence"}','Driving Licence (Sarathi / Parivahan) is a central government service under Ministry of Road Transport and Highways in the Transport category, available both.','Driving Licence (Sarathi / Parivahan) is Application for learner''s licence, driving licence, and renewals through the Parivahan Sarathi portal. Eligibility: Minimum age 16 (gearless <50cc) / 18 (LMV); pass driving test.. Benefits: Legal authorisation to drive; valid identity/address proof.. You can apply both via https://parivahan.gov.in. Processing time is typically Learner''s licence same day (online test); DL after driving test, ~7-30 days. and fees are Learner''s ~Rs.150; DL ~Rs.200+ (varies by state RTO)..','["How do I apply for Driving Licence (Sarathi / Parivahan)?", "What documents are required for Driving Licence (Sarathi / Parivahan)?", "What is the fee for Driving Licence (Sarathi / Parivahan)?", "Who is eligible for Driving Licence (Sarathi / Parivahan)?", "How long does Driving Licence (Sarathi / Parivahan) take to process?", "What is the official website for Driving Licence (Sarathi / Parivahan)?"]','["Uploading documents that do not match the name/details on record.", "Using an expired or unlinked mobile number for OTP verification.", "Submitting low-resolution or oversized document scans.", "Selecting the wrong state/district or service category.", "Not saving the application/reference number after submission."]','["Do I need to visit an office in person for Driving Licence (Sarathi / Parivahan)?", "Can I track my Driving Licence (Sarathi / Parivahan) application status online?", "What should I do if my Driving Licence (Sarathi / Parivahan) application is rejected?", "Are there any state-specific rules for Driving Licence (Sarathi / Parivahan) in Maharashtra?"]','{"driving","driving licence","learner licence","licence","parivahan","rto","sarathi","transport"}','https://parivahan.gov.in/parivahan/','html','2025-01-01',1,'0b7f1cad46e25d2407b6ddd933f0e620f4952c985ace22e35c78955464fd4848') ON CONFLICT (service_id) DO NOTHING;
