ied)..','["How do I apply for Aadhaar Enrolment / Update?", "What documents are required for Aadhaar Enrolment / Update?", "What is the fee for Aadhaar Enrolment / Update?", "Who is eligible for Aadhaar Enrolment / Update?", "How long does Aadhaar Enrolment / Update take to process?", "What is the official website for Aadhaar Enrolment / Update?"]','["Uploading documents that do not match the name/details on record.", "Using an expired or unlinked mobile number for OTP verification.", "Submitting low-resolution or oversized document scans.", "Selecting the wrong state/district or service category.", "Not saving the application/reference number after submission."]','["Do I need to visit an office in person for Aadhaar Enrolment / Update?", "Can I track my Aadhaar Enrolment / Update application status online?", "What should I do if my Aadhaar Enrolment / Update application is rejected?", "Are there any state-specific rules for Aadhaar Enrolment / Update in Maharashtra?"]','{"aadhaar","enrolment","identity","kyc","uid","update"}','https://uidai.gov.in/en/my-aadhaar/get-aadhaar.html','html','2025-01-01',1,'e8491a29c81fd3e643fa0401932bf8f1f6c0a5678a0e0e015b87a861ec91d2a5') ON CONFLICT (service_id) DO NOTHING;
